<?php require_once __DIR__.'/../includes/functions.php'; require_login('admin'); $pdo=db(); $stats=['children'=>(int)$pdo->query('SELECT COUNT(*) FROM children')->fetchColumn(),'hospitals'=>(int)$pdo->query("SELECT COUNT(*) FROM hospitals WHERE status='active'")->fetchColumn(),'pending'=>(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='requested'")->fetchColumn(),'completed'=>(int)$pdo->query("SELECT COUNT(*) FROM vaccination_records")->fetchColumn()]; $bookings=$pdo->query("SELECT b.*,c.full_name child_name,u.name parent_name,h.name hospital_name,v.name vaccine_name FROM bookings b JOIN children c ON c.id=b.child_id JOIN users u ON u.id=b.parent_id JOIN hospitals h ON h.id=b.hospital_id JOIN vaccines v ON v.id=b.vaccine_id ORDER BY b.created_at DESC LIMIT 12")->fetchAll(); $pageTitle='Admin dashboard'; require __DIR__.'/../includes/header.php'; ?>
<div class="dashboard-head"><div><span class="eyebrow">ADMINISTRATION</span><h1>System overview</h1><p>Monitor requests, records, and participating hospitals.</p></div><a class="button primary" href="<?=BASE_URL?>/admin/manage.php">Manage system →</a></div><div class="stat-grid"><div class="stat-card"><small>Registered children</small><strong><?=$stats['children']?></strong><span>Child profiles</span></div><div class="stat-card"><small>Active hospitals</small><strong><?=$stats['hospitals']?></strong><span>Care providers</span></div><div class="stat-card"><small>Requests to review</small><strong><?=$stats['pending']?></strong><span>Awaiting decision</span></div><div class="stat-card"><small>Vaccinations recorded</small><strong><?=$stats['completed']?></strong><span>Completed records</span></div></div><?php $statusCounts=[]; foreach(['requested','approved','completed','rejected','cancelled'] as $statusKey){$q=$pdo->prepare('SELECT COUNT(*) FROM bookings WHERE status=?');$q->execute([$statusKey]);$statusCounts[$statusKey]=(int)$q->fetchColumn();} $totalForChart=max(1,array_sum($statusCounts)); ?>
<section class="analytics-grid"><article class="panel analytics-panel"><div class="panel-head"><div><span class="eyebrow">LIVE OVERVIEW</span><h2>Appointment pipeline</h2><p>Current status distribution</p></div><span class="live-pill"><i></i> Updated now</span></div><div class="pipeline-bars"><?php foreach(['requested'=>'Requested','approved'=>'Approved','completed'=>'Completed','rejected'=>'Rejected','cancelled'=>'Cancelled'] as $key=>$label):$pct=round($statusCounts[$key]/$totalForChart*100);?><div class="pipeline-row"><div class="pipeline-label"><span><?=e($label)?></span><strong><?=$statusCounts[$key]?></strong></div><div class="pipeline-track"><span class="pipeline-fill fill-<?=e($key)?>" style="width:<?=$pct?>%"></span></div></div><?php endforeach;?></div><div class="analytics-foot"><span><?=array_sum($statusCounts)?> total requests</span><span><?=round($statusCounts['completed']/$totalForChart*100)?>% completed</span></div></article><article class="panel report-panel"><span class="eyebrow">REPORT CENTRE</span><h2>Make your data useful.</h2><p>Export current system records for your project demo, reporting or spreadsheet review.</p><a class="report-link" href="<?=BASE_URL?>/admin/report.php?type=appointments"><span class="report-icon">↧</span><span><b>Appointments report</b><small>CSV · booking statuses and schedules</small></span><strong>→</strong></a><a class="report-link" href="<?=BASE_URL?>/admin/report.php?type=vaccinations"><span class="report-icon mint-icon">✓</span><span><b>Vaccination records</b><small>CSV · completed vaccination history</small></span><strong>→</strong></a></article></section>
<section class="panel"><div class="panel-head"><div><h2>Recent appointments</h2><p>Latest requests across the system</p></div><a href="<?=BASE_URL?>/admin/manage.php">View management →</a></div><div class="table-wrap"><table><thead><tr><th>Child / parent</th><th>Vaccine</th><th>Hospital</th><th>Date</th><th>Status</th></tr></thead><tbody><?php if(!$bookings):?><tr><td colspan="5" class="empty">No bookings yet. Appointments will appear here when parents request them.</td></tr><?php endif; foreach($bookings as $b):?><tr><td><b><?=e($b['child_name'])?></b><br><small><?=e($b['parent_name'])?></small></td><td><?=e($b['vaccine_name'])?></td><td><?=e($b['hospital_name'])?></td><td><?=e($b['appointment_date'])?> <small><?=e(substr($b['appointment_time'],0,5))?></small></td><td><span class="badge <?=e($b['status'])?>"><?=e(ucfirst($b['status']))?></span></td></tr><?php endforeach;?></tbody></table></div></section><section class="quick-links"><a class="quick-link" href="<?=BASE_URL?>/admin/manage.php#bookings"><b>Review bookings →</b><small>Approve or reject appointment requests.</small></a><a class="quick-link" href="<?=BASE_URL?>/admin/manage.php#hospitals"><b>Hospitals →</b><small>Activate and maintain hospital listings.</small></a><a class="quick-link" href="<?=BASE_URL?>/admin/manage.php#vaccines"><b>Vaccine catalogue →</b><small>Maintain vaccine names and availability.</small></a></section><?php require __DIR__.'/../includes/footer.php'; ?>
